#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007;

struct F {
  ll v;
  F(ll v=0): v(v%MOD) {}
  F operator+(const F& o) const { return F((v+o.v)%MOD); }
  F operator-(const F& o) const { return F((v - o.v + MOD)%MOD); }
  F operator*(const F& o) const { return F((v*o.v)%MOD); }
  F& operator+=(const F& o) { v = (v+o.v)%MOD; return *this; }
  F& operator-=(const F& o) { v = (v - o.v + MOD)%MOD; return *this; }
  F& operator*=(const F& o) { v = (v*o.v)%MOD; return *this; }
  F inv() const {
    ll a= v, b=MOD, u=1, v2=0;
    while(b){
      ll t= a/b;
      swap(a, b);
      b= b - t* b;
      swap(u, v2);
      v2= v2 - t* u;
    }
    return F(u);
  }
  F operator/(const F& o) const { return *this * o.inv(); }
};

vector<vector<F>> mat_mul(const vector<vector<F>>& a, const vector<vector<F>>& b) {
  int n= a.size(), m= a[0].size(), p= b[0].size();
  vector<vector<F>> res(n, vector<F>(p,0));
  for(int i=0; i< n; i++){
    for(int j=0; j< p; j++){
      for(int k=0; k< m; k++){
        res[i][j] += a[i][k]*b[k][j];
      }
    }
  }
  return res;
}

vector<F> mat_vec(const vector<vector<F>>& m, const vector<F>& v) {
  int n= m.size(), m2= v.size();
  vector<F> res(n,0);
  for(int i=0; i< n; i++){
    for(int j=0; j< m2; j++){
      res[i] += m[i][j]*v[j];
    }
  }
  return res;
}

vector<vector<F>> make2D(int d1, int d2, F val) {
  return vector<vector<F>>(d1, vector<F>(d2, val));
}

vector<vector<vector<F>>> make3D(int d1, int d2, int d3, F val) {
  return vector<vector<vector<F>>>(
      d1, vector<vector<F>>(d2, vector<F>(d3, val)));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int64 n; int d;
  cin >> n >> d;

  auto shifts= make3D<F>(d, d+1, d+1, 0);
  for(int k=0; k< d; k++){
    for(int i=0; i< d; i++){
      shifts[k][i][(i+k)%d]=1;
    }
    shifts[k][d][d]=1;
  }

  auto units= make3D<F>(d, d+1, d+1, 0);
  for(int k=0; k< d; k++){
    for(int i=0; i<= d; i++){
      units[k][i][i]=1;
    }
    for(int i=0; i<= d; i++){
      units[k][k][i]=1;
    }
  }

  auto identity= make2D<F>(d+1, d+1, 0);
  for(int i=0; i<= d; i++){
    identity[i][i]=1;
  }

  unordered_map<ll, vector<vector<F>>> cache;

  function<vector<vector<F>>(ll)> get_matrix= [&](ll p) -> vector<vector<F>> {
    if(cache.count(p)) return cache[p];
    if(p<= d){
      auto mat= identity;
      for(int k=0; k< p; k++){
        mat= mat_mul(units[k], mat);
      }
      cache[p]= mat;
      return mat;
    }
    ll child_p= d;
    while((p+ child_p -1)/ child_p > d) child_p*= d;
    auto child= get_matrix(child_p);
    auto mat= child;
    ll rem= p- child_p;
    for(int k=1; k< d; k++){
      if(rem>= child_p){
        mat= mat_mul(shifts[d -k], mat);
        mat= mat_mul(mat, shifts[k]);
        mat= mat_mul(mat, child);
        rem-= child_p;
      } else if(rem>0){
        auto rem_mat= get_matrix(rem);
        mat= mat_mul(shifts[d -k], mat);
        mat= mat_mul(mat, rem_mat);
        mat= mat_mul(mat, shifts[k]);
        rem=0;
      } else break;
    }
    cache[p]= mat;
    return mat;
  };

  auto matrix= get_matrix(n);
  vector<F> base_vec(d+1,0);
  base_vec[d]=1;
  auto final_vec= mat_vec(matrix, base_vec);
  F ans=0;
  for(auto& v: final_vec) ans+=v;
  cout<< ans.get()<<"\n";
}
